  ro_cells usegs m T_ANYEX_OBJECT_FNS [C8 (wz P_ANYEX_FN_DESTROY)] ->
  stk usegs m lo (bv_unsigned sp) -> lo + ANYEX_BASE_DTOR_STACK <= bv_unsigned sp -> hceil <= lo ->
